/*
* Custom tool executed inside the Flowise container.
* $vars.sharedDirectory can override the default /data/shared path.
*/

const fs = require('fs');
const path = require('path');

const baseDir = $vars.sharedDirectory || '/data/shared';
const safeTitle = ($document_title || 'note').replace(/[^a-z0-9-_]+/gi, '-');
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const fileName = `${safeTitle}-${timestamp}.md`;
const filePath = path.join(baseDir, fileName);

try {
    fs.mkdirSync(baseDir, { recursive: true });
    const header = $document_title ? `# ${$document_title}

` : '';
    fs.writeFileSync(filePath, `${header}${$document_text}
`, 'utf8');
    return `Created markdown document at ${filePath}`;
} catch (error) {
    console.error(error);
    throw new Error('Failed to write markdown document: ' + error.message);
}
